 835→func TestRunWingmanApply_EndedPhaseProceeds(t *testing.T) {
 836→	t.Parallel()
 837→
 838→	// This test verifies that runWingmanApply does NOT abort when the session
 839→	// phase is ENDED (the bug fix). We can't test the full auto-apply (it
 840→	// spawns claude CLI), but we can verify it passes the phase check.
 841→	tmpDir := t.TempDir()
 842→	entireDir := filepath.Join(tmpDir, ".entire")
 843→	if err := os.MkdirAll(entireDir, 0o755); err != nil {
 844→		t.Fatal(err)
 845→	}
 846→
 847→	// Create REVIEW.md
 848→	reviewPath := filepath.Join(entireDir, "REVIEW.md")
 849→	if err := os.WriteFile(reviewPath, []byte("review content"), 0o644); err != nil {
 850→		t.Fatal(err)
 851→	}
 852→
 853→	// Create wingman state
 854→	saveWingmanStateDirect(tmpDir, &WingmanState{
 855→		SessionID:  "sess-ended",
 856→		FilesHash:  "hash1",
 857→		ReviewedAt: time.Now(),
 858→	})
 859→
 860→	// Create session state dir with ENDED phase
 861→	sessDir := filepath.Join(tmpDir, ".git", "entire-sessions")
 862→	if err := os.MkdirAll(sessDir, 0o755); err != nil {
 863→		t.Fatal(err)
 864→	}
 865→	if err := os.WriteFile(filepath.Join(sessDir, "sess-ended.json"), []byte(`{"phase":"ended"}`), 0o644); err != nil {
 866→		t.Fatal(err)
 867→	}
 868→
 869→	// runWingmanApply will pass the phase check but fail at triggerAutoApply
 870→	// (no claude CLI). The important thing is it doesn't return nil early
 871→	// with "session became active" — it should get past the phase check.
 872→	err := runWingmanApply(tmpDir)
 873→	if err == nil {
 874→		t.Log("runWingmanApply returned nil (auto-apply succeeded or no claude CLI)")
 875→	} else {
 876→		// Expected: fails at triggerAutoApply because claude CLI isn't available
 877→		if strings.Contains(err.Error(), "session became active") {
 878→			t.Error("should not abort with 'session became active' for ENDED phase")
 879→		}
 880→		t.Logf("runWingmanApply failed as expected (no claude CLI): %v", err)
 881→	}
 882→
 883→	// Verify apply was attempted (state should be updated)
 884→	state := loadWingmanStateDirect(tmpDir)
 885→	if state == nil {
 886→		t.Fatal("expected wingman state to exist")
 887→	}
 888→	if state.ApplyAttemptedAt == nil {
 889→		t.Error("ApplyAttemptedAt should be set after passing phase check")
 890→	}
 891→}
