 11→func TestClaudeGenerator_GitIsolation(t *testing.T) {
 12→	var capturedCmd *exec.Cmd
 13→
 14→	response := `{"result":"{\"intent\":\"test\",\"outcome\":\"test\",\"learnings\":{\"repo\":[],\"code\":[],\"workflow\":[]},\"friction\":[],\"open_items\":[]}"}`
 15→
 16→	gen := &ClaudeGenerator{
 17→		CommandRunner: func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
 18→			// Capture the command but return something that produces valid output
 19→			cmd := exec.CommandContext(ctx, "sh", "-c", "printf '%s' '"+response+"'")
 20→			capturedCmd = cmd
 21→			return cmd
 22→		},
 23→	}
 24→
 25→	// Set GIT_* vars that would normally be inherited from a git hook
 26→	t.Setenv("GIT_DIR", "/some/repo/.git")
 27→	t.Setenv("GIT_WORK_TREE", "/some/repo")
 28→	t.Setenv("GIT_INDEX_FILE", "/some/repo/.git/index")
 29→
 30→	input := Input{
 31→		Transcript: []Entry{
 32→			{Type: EntryTypeUser, Content: "Hello"},
 33→		},
 34→	}
 35→
 36→	_, err := gen.Generate(context.Background(), input)
 37→	if err != nil {
 38→		t.Fatalf("unexpected error: %v", err)
 39→	}
 40→
 41→	if capturedCmd == nil {
 42→		t.Fatal("command was not captured")
 43→	}
 44→
 45→	// Verify cmd.Dir is set to os.TempDir()
 46→	if capturedCmd.Dir != os.TempDir() {
 47→		t.Errorf("cmd.Dir = %q, want %q", capturedCmd.Dir, os.TempDir())
 48→	}
 49→
 50→	// Verify no GIT_* env vars in the command's environment
 51→	for _, env := range capturedCmd.Env {
 52→		if strings.HasPrefix(env, "GIT_") {
 53→			t.Errorf("found GIT_* env var in subprocess: %s", env)
 54→		}
 55→	}
 56→}
